css.value:
* { 
    color: var(--Text-text--tertiary, #454D5B);
font-family: Lato;
font-size: 12px;
font-style: normal;
font-weight: 400;
line-height: normal;
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Click check compatibility',
		value: {
			'Session id': api.context.props.experienceProperties.upgrade_session_id.value
		}
	};
})

