targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Complete preview app upgrades',
		value: {
			'Session id': api.context.props.experienceProperties.upgrade_session_id.value,
			'App count': api.state.storePreviewTableCount,
			'Error count': api.state.errorCount
		}
	};
})

